-- Description corrections only: no observations, weights or scores change.
INSERT OR IGNORE INTO corrections (
  id, published_at, affected_indicator, original_value, corrected_value, reason
) VALUES (
  '2026-10-28-source-definition-labels', strftime('%Y-%m-%dT%H:%M:%fZ', 'now'),
  'mortgage_2y_fix, gbp_twi, real_regular_pay, payroll_mom and housing_trajectory descriptions',
  'Descriptions incorrectly called IUMBV34 an effective rate, XUDLBK67 broad sterling, A3WW regular pay, K54L a 2015-based index and quarterly completions net housing additions',
  'Quoted 2-year 75% LTV mortgage rate; standard sterling effective index; real total-pay growth including bonuses; regular-pay index 2000=100; annualised new-build completions against a stated 300,000-home benchmark',
  'Independent publisher definitions were checked alongside numerical source matching. The existing numeric series and legacy indicator IDs are retained; this corrects descriptions rather than splicing different measures into the history. ONS A3WW is seasonally adjusted real total-pay growth, including bonuses, measured year-on-year in the three-month average. K54L is the regular-pay index excluding arrears, with 2000=100. The housing calculation uses quarterly seasonally adjusted new-build completions multiplied by four, divided by 300,000; it does not measure net additional dwellings or an OBR forecast. The mortgage series is a quoted rate rather than an interest-income-over-balances effective rate, and XUDLBK67 is the standard sterling effective exchange-rate index rather than the broad XUDLBK82 series. No score movement is caused by these wording corrections. Sources: https://www.ons.gov.uk/employmentandlabourmarket/peopleinwork/earningsandworkinghours/timeseries/a3ww/emp ; https://www.ons.gov.uk/employmentandlabourmarket/peopleinwork/earningsandworkinghours/timeseries/k54l/emp ; https://www.bankofengland.co.uk/boeapps/database/FromShowColumns.asp?searchText=exchange+rates ; https://www.bankofengland.co.uk/-/media/boe/files/statistics/bankstats-articles/2015/historical-sources-of-mortgage-interest-rate-statistics---bankstats-article.pdf ; https://www.gov.uk/government/statistical-data-sets/live-tables-on-house-building .'
);
